"""``docs/llms.txt`` is generated by ``scripts/render_llms_txt.py`` and must stay current."""

from __future__ import annotations

import importlib.util
import re
import sys
from pathlib import Path
from types import ModuleType

import pytest

ROOT = Path(__file__).resolve().parents[2]

if sys.version_info < (3, 11):  # pragma: no cover - Python 3.10
    pytest.importorskip("tomli")
if not (ROOT / "scripts" / "render_llms_txt.py").is_file():  # pragma: no cover - the sdist has no scripts/
    pytest.skip("scripts/ is not in this tree", allow_module_level=True)


def _script() -> ModuleType:
    spec = importlib.util.spec_from_file_location("render_llms_txt", ROOT / "scripts" / "render_llms_txt.py")
    assert spec is not None
    assert spec.loader is not None
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_llms_txt_is_current() -> None:
    assert _script().main(["--check"]) == 0, "run: python scripts/render_llms_txt.py"


def test_llms_txt_shape() -> None:
    text = (ROOT / "docs" / "llms.txt").read_text(encoding="utf-8")
    lines = text.splitlines()
    assert lines[0] == "# even-simpler-salesforce"
    assert lines[2].startswith("> ")
    links = re.findall(r"\]\((https://[^)]+)\)", text)
    raw = "https://raw.githubusercontent.com/Uttsavv/even-simpler-salesforce/main/"
    assert links
    assert all(link.startswith(raw) for link in links)
    for link in links:  # every link names a file in this repository
        assert (ROOT / link.removeprefix(raw)).is_file(), link
    assert "reference/index.md" not in text
    assert "changelog.md" not in text
    assert "## Agent skills" in text
    assert "esf-probe/SKILL.md" in text
    assert text.index("## Optional") > text.index("## Agent skills")


def test_check_reports_a_stale_file(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    mod = _script()
    monkeypatch.setattr(mod, "TARGET", tmp_path / "llms.txt")
    assert mod.main(["--check"]) == 1
    assert mod.main([]) == 0
    assert mod.main(["--check"]) == 0
